adcs_mat3_t prod;
double det;
double err;

if ((dcm == NULL) || (valid == NULL) || (determinant == NULL) ||
    (orthogonality_error == NULL)) {
    return ADCS_E_NULL;
}

if ((!isfinite(tolerance)) || (tolerance < 0.0)) {
    return ADCS_E_RANGE;
}

{
    size_t i;
    size_t j;
    for (i = 0U; i < 3U; i++) {
        for (j = 0U; j < 3U; j++) {
            if (!isfinite(dcm->m[i][j])) {
                return ADCS_E_RANGE;
            }
        }
    }
}

det = adcs_mat3_det(dcm);
if (!isfinite(det) || (det <= 0.0)) {
    return ADCS_E_RANGE;
}

ct = adcs_mat3_transpose(dcm);
prod = adcs_mat3_mul(dcm, &ct);
err = adcs_mat3_frobenius_error_identity(&prod);

if (!isfinite(err)) {
    return ADCS_E_RANGE;
}

if (err <= tolerance) {
    *valid = 1;
} else {
    *valid = 0;
}

*determinant = det;
*orthogonality_error = err;

return ADCS_OK;

